// STRATTON CANDIDATE ENGINE — CONFIG
// The same node appears at the head of all three workflows. Edit it in one, paste it
// into the other two; validate.py checks that they have not drifted apart.
//
// Any key left blank means that step is SKIPPED, not that the run fails. That is what
// lets the whole engine be demonstrated on a screen-share before a single credential,
// phone number or ATS sandbox exists.

// ---------------------------------------------------------------- Which client is this
// Everything the engine writes carries this id. One n8n instance runs every client;
// two clients can never see each other's rows because every query is filtered on it and
// every table has an RLS policy that says the same thing.
const CLIENT_SLUG = 'stratton';
const CLIENT_ID   = '';          // the clients.id uuid from Supabase. Blank -> demo mode.

// ---------------------------------------------------------------- Supabase
// SUPABASE_URL blank -> the engine runs against sample/ data and writes nothing.
const SUPABASE_URL          = '';   // https://xxxxxxxx.supabase.co
const SUPABASE_SERVICE_KEY  = '';   // service_role key. n8n credential store is better;
                                    // this is here so the template runs before that exists.

// ---------------------------------------------------------------- The ATS
// One block, six vendors. Only ATS_VENDOR and the credentials change between clients —
// the field mapping below is what actually makes a new ATS work.
const ATS_VENDOR   = 'bullhorn';    // bullhorn | avionte | ceipal | jobdiva | recruitcrm | salesforce | generic
const ATS_BASE_URL = '';            // e.g. https://rest99.bullhornstaffing.com/rest-services/abcde
const ATS_TOKEN    = '';            // BhRestToken / bearer. Blank -> ATS steps are skipped.

// How THIS client's ATS names things. This object is the entire onboarding cost of a new
// ATS: point each of our field names at theirs, dotted paths allowed.
const ATS_FIELDS = {
  job: {
    id:            'id',
    title:         'title',
    description:   'publicDescription',
    skills:        'skillList',            // comma string or array, both handled
    city:          'address.city',
    state:         'address.state',
    pay_rate:      'payRate',
    shift:         'customText1',
    employment:    'employmentType',
    recruiter:     'owner.name',
    recruiter_mail:'owner.email'
  },
  candidate: {
    id:         'id',
    first_name: 'firstName',
    last_name:  'lastName',
    email:      'email',
    phone:      'mobile',
    phone_alt:  'phone',
    title:      'occupation',
    skills:     'skillSet',
    city:       'address.city',
    state:      'address.state',
    status:     'status'
  }
};

// Where candidates come from when the ATS is not connected. The search endpoint per
// vendor differs; the shape after `normalise the candidates` does not.
const ATS_CANDIDATE_SEARCH_LIMIT = 200;   // ask the ATS for this many, score them all
const ENROLL_TOP_N               = 25;    // enroll only the best this many

// ---------------------------------------------------------------- The AI reader
// Most job orders are prose. `skillList` is empty far more often than a vendor demo
// suggests, and matching 20,000 candidates against an empty skill list finds nobody.
//
// So when the ATS gives us fewer than MIN_SKILLS_BEFORE_AI real skills, the description is
// read once and turned into a structured requirement list. It runs ONCE PER JOB ORDER, not
// per candidate — a few hundred tokens per campaign, not per person.
//
// Blank key -> the step is skipped and the keyword rules stand on their own.
const AI_API_KEY = '';
const AI_MODEL   = 'claude-opus-5';
const AI_EFFORT  = 'low';        // low | medium | high — extraction is not a hard problem
const MIN_SKILLS_BEFORE_AI = 2;  // at or below this many ATS skills, ask the model

// The model may only return skills. It is never asked who to contact, and never asked to
// score anybody — those stay in code where they can be audited and re-run.
const AI_MAX_SKILLS = 12;

// ---------------------------------------------------------------- Matching
// A transparent score, on purpose. A staffing manager can read why someone was
// contacted, which they cannot do with an embedding similarity.
const MATCH = {
  required_skill:   18,   // per required skill the candidate has
  nice_skill:        6,
  same_city:        12,
  same_state:        6,
  title_overlap:    14,   // words shared between their title and the job title
  recent_activity:  10,   // ATS status suggests they are actively looking
  has_mobile:        8    // no mobile means no SMS and no call. Weighted, not fatal.
};
const MIN_MATCH_SCORE = 40;   // below this, stored with a reason and never contacted

// Statuses in the client's ATS that mean "do not contact this person". Placed candidates
// are the one that gets people in trouble.
const ATS_EXCLUDE_STATUSES = ['Placed', 'Do Not Contact', 'Blacklisted', 'Inactive',
  'Deceased', 'Archived'];

// ---------------------------------------------------------------- The outreach ladder
// Copied onto the campaign at launch, so editing this never changes the behaviour of a
// campaign already running. delay_hours is measured from the previous attempt.
const SEQUENCE = [
  { step: 1, channel: 'sms',   delay_hours: 0,
    template: 'Hi {{first_name}}, it is {{recruiter_name}} at {{client_name}}. We have a '
            + '{{job_title}} role in {{job_city}}{{pay_phrase}}. Interested in hearing more? '
            + 'Reply YES or STOP to opt out.' },
  { step: 2, channel: 'sms',   delay_hours: 20,
    template: 'Hi {{first_name}}, following up on the {{job_title}} position in {{job_city}}. '
            + 'Still open. Reply YES and I will call you, or STOP to opt out.' },
  { step: 3, channel: 'voice', delay_hours: 26,
    agent_note: 'Second contact. They have had two texts and not replied. Keep it under '
              + '90 seconds and offer to text the details instead.' },
  { step: 4, channel: 'sms',   delay_hours: 48,
    template: 'Last note from me on the {{job_title}} role, {{first_name}} — reply YES if '
            + 'you would like the details, otherwise I will close it out. STOP to opt out.' }
];

// ---------------------------------------------------------------- When we are allowed
// TCPA is the reason this block exists. Quiet hours are evaluated in the CANDIDATE's
// timezone, not the server's and not the recruiter's.
const QUIET_HOURS_START = 21;    // no outbound at or after 21:00 local
const QUIET_HOURS_END   = 8;     // no outbound before 08:00 local
const SEND_ON_WEEKENDS  = false;
const DEFAULT_TIMEZONE  = 'America/New_York';

const RUNNER_BATCH_SIZE = 50;    // enrollments claimed per 15-minute run
const DAILY_SEND_CAP    = 500;   // hard ceiling per client per day, enforced in code
const LEASE_SECONDS     = 300;   // how long a claimed row stays claimed

// A number we have already touched today is not touched again, whatever the ladder says.
const MIN_HOURS_BETWEEN_TOUCHES = 18;

// ---------------------------------------------------------------- Twilio
const TWILIO_ACCOUNT_SID  = '';
const TWILIO_AUTH_TOKEN   = '';   // also the key the inbound webhook signature is checked with
const TWILIO_FROM_NUMBER  = '';   // +1XXXXXXXXXX, or a Messaging Service SID below
const TWILIO_MESSAGING_SID= '';   // MGxxxx. Preferred at volume — handles the number pool.
const TWILIO_STATUS_CALLBACK = '';// https://n8n.example.com/webhook/stratton-inbound

// Twilio error codes that mean "this will never work" — retrying them wastes money and
// looks like a loop. Everything else is treated as transient and backed off.
const PERMANENT_SMS_ERRORS = ['21211', '21610', '21614', '21408', '30003', '30005', '30006'];
//                            bad num  optout  not mobile geo-perm unreach  unknown  landline

// ---------------------------------------------------------------- Retell AI
const RETELL_API_KEY   = '';
const RETELL_AGENT_ID  = '';      // the outbound screening agent
const RETELL_FROM_NUMBER = '';    // a number bought inside Retell, or a Twilio number imported
const RETELL_WEBHOOK_SECRET = ''; // verifies the call_analyzed callback

// ---------------------------------------------------------------- Qualification
// The structured criteria. The AI agent is asked to fill these in; it is not asked to
// decide. The decision is this object, evaluated in a Code node, identically every time.
const QUALIFY = {
  must: [
    { key: 'interested',        equals: true,  label: 'said they are interested' },
    { key: 'authorized_to_work', equals: true, label: 'authorised to work' },
    { key: 'can_start_within_days', lte: 21,   label: 'can start within three weeks' }
  ],
  score: [
    { key: 'years_experience',  gte: 2,    points: 25, label: '2+ years experience' },
    { key: 'has_reliable_transport', equals: true, points: 15, label: 'has transport' },
    { key: 'shift_match',       equals: true, points: 20, label: 'shift works for them' },
    { key: 'rate_acceptable',   equals: true, points: 25, label: 'accepts the rate' },
    { key: 'certifications_valid', equals: true, points: 15, label: 'certifications current' }
  ],
  pass_mark: 60,
  // Anything the AI could not establish is null, and null never passes a `must`. An
  // unanswered question is a not-qualified, not an assumed yes.
  review_band: 15   // within this many points of the pass mark -> human review, not a rejection
};

// Words that stop everything, checked before anything else is done with a message.
const OPT_OUT_KEYWORDS = ['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit',
  'remove me', 'opt out', 'optout', 'do not text', 'dont text', 'take me off'];
const POSITIVE_KEYWORDS = ['yes', 'yeah', 'yep', 'y', 'sure', 'interested', 'ok', 'okay',
  'tell me more', 'more info', 'call me', 'sounds good', 'im in', "i'm in"];
const NEGATIVE_KEYWORDS = ['no', 'not interested', 'no thanks', 'nope', 'pass',
  'already have a job', 'found a job', 'not looking'];

// ---------------------------------------------------------------- Scheduling
const CALENDAR_PROVIDER   = 'google';   // google | microsoft | none
const RECRUITER_CALENDARS = {
  // recruiter email -> calendar id. Blank object -> the job order's recruiter_email is used
  // as the calendar id, which is what Google does by default anyway.
};
const INTERVIEW_MINUTES     = 30;
const BOOKING_LEAD_HOURS    = 18;    // never book sooner than this
const BOOKING_WINDOW_DAYS   = 5;     // look this far ahead for a slot
const BOOKING_HOURS         = [9, 10, 11, 13, 14, 15, 16];   // recruiter local hours

// ---------------------------------------------------------------- Telling people
const SLACK_WEBHOOK_URL = '';    // blank -> no Slack notification
const NOTIFY_RECRUITER_EMAIL = true;

// ---------------------------------------------------------------- The safety switch
// Ships in the safest position. Nothing reaches a candidate until someone deliberately
// changes TEST_RUN.
const TEST_RUN    = true;   // true -> no SMS, no call, no ATS write, no calendar event
const TEST_PHONE  = '';     // blank -> preview only. Set -> messages really send, to here.
const DRY_RUN_DB  = false;  // true -> Supabase reads happen, writes do not

// Gives every provider call a deterministic fake response so the three workflows can be
// watched end to end before any account exists. FORCES preview whatever the two above say,
// because a fabricated Twilio SID must never be able to reach a real phone.
const DEMO_MODE = true;

// Quiet hours are real, and at 01:00 the runner correctly defers every single row — which
// is the right behaviour and a useless thing to film. This ignores the quiet-hours check
// so a walkthrough can be recorded at any hour.
//
// It is honoured ONLY when DEMO_MODE is on, and DEMO_MODE forces preview, so this switch
// can never cause a real message at 3am. Turning DEMO_MODE off disarms it automatically.
const DEMO_ANY_HOUR = true;

// =============================================================================
const MODE = DEMO_MODE ? 'preview'
           : (TEST_RUN !== true ? 'live' : (TEST_PHONE.trim() !== '' ? 'test' : 'preview'));

const supabase_enabled = SUPABASE_URL.trim() !== '' && SUPABASE_SERVICE_KEY.trim() !== '';
const ats_enabled      = ATS_BASE_URL.trim() !== '' && ATS_TOKEN.trim() !== '';
const twilio_enabled   = TWILIO_ACCOUNT_SID.trim() !== '' && TWILIO_AUTH_TOKEN.trim() !== ''
                      && (TWILIO_FROM_NUMBER.trim() !== '' || TWILIO_MESSAGING_SID.trim() !== '');
const retell_enabled   = RETELL_API_KEY.trim() !== '' && RETELL_AGENT_ID.trim() !== '';

return [{
  json: {
    client_slug: CLIENT_SLUG,
    client_id:   CLIENT_ID,
    client_name: CLIENT_SLUG.charAt(0).toUpperCase() + CLIENT_SLUG.slice(1),

    supabase_url: SUPABASE_URL.replace(/\/+$/, ''),
    supabase_key: SUPABASE_SERVICE_KEY,
    supabase_enabled: supabase_enabled,
    dry_run_db: DRY_RUN_DB === true,

    ats_vendor: ATS_VENDOR,
    ats_base_url: ATS_BASE_URL.replace(/\/+$/, ''),
    ats_token: ATS_TOKEN,
    ats_fields: ATS_FIELDS,
    ats_enabled: ats_enabled,
    ats_exclude_statuses: ATS_EXCLUDE_STATUSES,
    ats_search_limit: ATS_CANDIDATE_SEARCH_LIMIT,

    ai_key: AI_API_KEY,
    ai_model: AI_MODEL,
    ai_effort: AI_EFFORT,
    ai_max_skills: AI_MAX_SKILLS,
    min_skills_before_ai: MIN_SKILLS_BEFORE_AI,
    ai_enabled: AI_API_KEY.trim() !== '',

    match: MATCH,
    min_match_score: MIN_MATCH_SCORE,
    enroll_top_n: ENROLL_TOP_N,

    sequence: SEQUENCE,
    quiet_hours_start: QUIET_HOURS_START,
    quiet_hours_end: QUIET_HOURS_END,
    send_on_weekends: SEND_ON_WEEKENDS,
    default_timezone: DEFAULT_TIMEZONE,
    runner_batch_size: RUNNER_BATCH_SIZE,
    daily_send_cap: DAILY_SEND_CAP,
    lease_seconds: LEASE_SECONDS,
    min_hours_between_touches: MIN_HOURS_BETWEEN_TOUCHES,

    twilio_sid: TWILIO_ACCOUNT_SID,
    twilio_token: TWILIO_AUTH_TOKEN,
    twilio_from: TWILIO_FROM_NUMBER,
    twilio_messaging_sid: TWILIO_MESSAGING_SID,
    twilio_status_callback: TWILIO_STATUS_CALLBACK,
    twilio_enabled: twilio_enabled,
    permanent_sms_errors: PERMANENT_SMS_ERRORS,

    retell_key: RETELL_API_KEY,
    retell_agent: RETELL_AGENT_ID,
    retell_from: RETELL_FROM_NUMBER,
    retell_secret: RETELL_WEBHOOK_SECRET,
    retell_enabled: retell_enabled,

    qualify: QUALIFY,
    opt_out_keywords: OPT_OUT_KEYWORDS,
    positive_keywords: POSITIVE_KEYWORDS,
    negative_keywords: NEGATIVE_KEYWORDS,

    calendar_provider: CALENDAR_PROVIDER,
    calendar_enabled: CALENDAR_PROVIDER !== 'none',
    recruiter_calendars: RECRUITER_CALENDARS,
    interview_minutes: INTERVIEW_MINUTES,
    booking_lead_hours: BOOKING_LEAD_HOURS,
    booking_window_days: BOOKING_WINDOW_DAYS,
    booking_hours: BOOKING_HOURS,

    slack_webhook_url: SLACK_WEBHOOK_URL,
    slack_enabled: SLACK_WEBHOOK_URL.trim() !== '',
    notify_recruiter_email: NOTIFY_RECRUITER_EMAIL === true,

    mode: MODE,
    test_phone: TEST_PHONE.trim(),
    demo_mode: DEMO_MODE === true,
    // Deliberately ANDed with DEMO_MODE here rather than trusted on its own, so the flag
    // cannot be left on by accident and quietly disable quiet hours in production.
    ignore_quiet_hours: DEMO_MODE === true && DEMO_ANY_HOUR === true,
    forced_preview: DEMO_MODE === true && TEST_RUN !== true,
    // The single flag every outbound gate reads. Nothing else decides whether to send.
    send_enabled: MODE !== 'preview',
    live_send: MODE === 'live',
    // Only a live run may touch the client's ATS or a recruiter's real calendar.
    writeback_enabled: MODE === 'live'
  }
}];

// Supabase is not connected, so there is no queue to read. In demo mode the runner
// substitutes a handful of due rows shaped exactly like `v_due_attempts` returns them —
// which is what lets the state machine, the quiet-hours logic and the message rendering all
// be watched working before a database exists.
//
// The four rows are deliberately at four different rungs of the ladder and in three
// different timezones, because that is what makes the interesting behaviour visible.
const cfg = $('config').first().json;

if (!cfg.demo_mode) {
  return [{
    json: {
      _no_due_rows: true,
      _outcome: 'Supabase not configured',
      _next_step: 'Fill in SUPABASE_URL and SUPABASE_SERVICE_KEY in the config node. Until '
        + 'then the runner has no queue to read and sends nothing, which is the correct '
        + 'behaviour rather than an error.'
    }
  }];
}

const seq = cfg.sequence;
const base = {
  client_id: '+1234567890+1234567890',
  campaign_id: '+1234567890+1234567890c1',
  job_order_id: '+1234567890+1234567890j1',
  client_slug: cfg.client_slug,
  quiet_hours_start: cfg.quiet_hours_start,
  quiet_hours_end: cfg.quiet_hours_end,
  daily_send_cap: cfg.daily_send_cap,
  job_title: 'Forklift Operator',
  job_city: 'Columbus',
  job_state: 'OH',
  pay_rate: 22.5,
  shift: '1st shift, Mon-Fri',
  recruiter_name: 'Dana Reyes',
  recruiter_email: 'user@example.com',
  sequence: seq,
  qualification: cfg.qualify,
  status: 'active'
};

const ago = (h) => new Date(Date.now() - h * 3600 * 1000).toISOString();

return [
  // Step 0: never contacted. Gets touch 1, an SMS.
  { json: Object.assign({}, base, {
      enrollment_id: 'e+1234567890-+1234567890',
      candidate_id: 'c+1234567890-+1234567890',
      first_name: 'Marcus', last_name: 'Ellison', phone_e164: '+1234567890',
      email: 'user@example.com', candidate_timezone: 'America/New_York',
      step: 0, attempts_made: 0, match_score: 74, next_attempt_at: ago(1) }) },

  // Step 1: had one text, no reply. Gets the follow-up.
  { json: Object.assign({}, base, {
      enrollment_id: 'e+1234567890-+1234567890',
      candidate_id: 'c+1234567890-+1234567890',
      first_name: 'Danielle', last_name: 'Okafor', phone_e164: '+1234567890',
      email: 'user@example.com', candidate_timezone: 'America/New_York',
      step: 1, attempts_made: 1, match_score: 68, next_attempt_at: ago(2) }) },

  // Step 2: two texts, silence. This one escalates to a Retell voice call.
  { json: Object.assign({}, base, {
      enrollment_id: 'e+1234567890-+1234567890',
      candidate_id: 'c+1234567890-+1234567890',
      first_name: 'Andre', last_name: 'Whitlock', phone_e164: '+1234567890',
      email: 'user@example.com', candidate_timezone: 'America/New_York',
      step: 2, attempts_made: 2, match_score: 61, next_attempt_at: ago(3) }) },

  // In Los Angeles. At 08:30 Eastern it is 05:30 for them — deferred, not sent.
  { json: Object.assign({}, base, {
      enrollment_id: 'e+1234567890-+1234567890',
      candidate_id: 'c+1234567890-+1234567890',
      first_name: 'Renata', last_name: 'Voss', phone_e164: '+1234567890',
      email: 'user@example.com', candidate_timezone: 'America/Los_Angeles',
      step: 0, attempts_made: 0, match_score: 55, next_attempt_at: ago(1) }) },

  // Finished the whole ladder and never replied. Becomes `exhausted`, which is an outcome,
  // not a failure.
  { json: Object.assign({}, base, {
      enrollment_id: 'e+1234567890-+1234567890',
      candidate_id: 'c+1234567890-+1234567890',
      first_name: 'Owen', last_name: 'Castellanos', phone_e164: '+1234567890',
      email: 'user@example.com', candidate_timezone: 'America/New_York',
      step: 4, attempts_made: 4, match_score: 44, next_attempt_at: ago(24) }) }
];

// The state machine. For every enrollment the database said was due, this decides which
// rung of the ladder is next, whether it is allowed to happen right now, and what exactly
// would be sent.
//
// Three properties this node is responsible for:
//
//   Quiet hours are evaluated in the CANDIDATE's timezone. A 9am campaign in New York is a
//   6am campaign in Los Angeles, and TCPA does not care which office set the schedule.
//
//   Nothing is sent from here. This node produces intent only; the send happens two nodes
//   later, behind the mode gate. That separation is what lets the whole runner be watched
//   in preview against real due rows.
//
//   The idempotency key is computed BEFORE the send, from facts that do not change on a
//   retry. If n8n dies between Twilio accepting the message and the attempt row being
//   written, the next run recomputes the same key, the insert conflicts, and the candidate
//   is not texted twice.
const cfg = $('config').first().json;
const now = new Date();

const rows = $input.all().map((i) => i.json)
  .filter((r) => r && r.enrollment_id && !r._no_due_rows);

// Anything outside plain ASCII flips a whole SMS to UCS-2. Written as a character-code
// scan rather than a regex so there is no escape sequence to get mangled in transit.
function hasNonAscii(s) {
  const str = String(s || '');
  for (let i = 0; i < str.length; i++) if (str.charCodeAt(i) > 127) return true;
  return false;
}

// Local wall-clock hour and weekday in an arbitrary IANA zone, without a date library.
// Intl is present in both the n8n Code sandbox and plain node, which keeps simulate.js
// honest about what will actually happen in production.
function localParts(iso, tz) {
  const d = iso ? new Date(iso) : new Date();
  try {
    const f = new Intl.DateTimeFormat('en-US', {
      timeZone: tz, hour: 'numeric', hour12: false, weekday: 'short'
    });
    const parts = f.formatToParts(d);
    const hour = Number((parts.find((p) => p.type === 'hour') || {}).value);
    const weekday = (parts.find((p) => p.type === 'weekday') || {}).value;
    return { hour: Number.isFinite(hour) ? hour % 24 : d.getUTCHours(), weekday: weekday };
  } catch (e) {
    // An unknown timezone string must not take the run down. Fall back and flag it.
    return { hour: d.getUTCHours(), weekday: 'Mon', _tz_error: String(tz) };
  }
}

function isQuiet(hour) {
  const s = Number(cfg.quiet_hours_start);
  const e = Number(cfg.quiet_hours_end);
  return s > e ? (hour >= s || hour < e)    // 21:00 -> 08:00 wraps midnight
               : (hour >= s && hour < e);
}

// The next moment this candidate may legally be contacted.
function nextAllowed(tz) {
  for (let h = 1; h <= 24 * 8; h++) {
    const t = new Date(now.getTime() + h * 3600 * 1000);
    const p = localParts(t.toISOString(), tz);
    const weekend = p.weekday === 'Sat' || p.weekday === 'Sun';
    if (!isQuiet(p.hour) && (cfg.send_on_weekends || !weekend)) {
      // Land on the hour, so a deferred batch does not fire at 08:03:17 like a robot.
      t.setUTCMinutes(0, 0, 0);
      return t.toISOString();
    }
  }
  return new Date(now.getTime() + 12 * 3600 * 1000).toISOString();
}

// Deterministic key. The same enrollment, channel and step give the same key forever.
// FNV-1a rather than a crypto import, because it only has to be stable and collision-safe
// across one client's attempts, and this runs in a sandbox with no require().
function keyFor(parts) {
  const s = parts.join('|');
  let h1 = 0x811c9dc5;
  let h2 = 0x01000193;
  for (let i = 0; i < s.length; i++) {
    h1 = Math.imul(h1 ^ s.charCodeAt(i), 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ s.charCodeAt(i), 0x85ebca6b) >>> 0;
  }
  return 'att_' + h1.toString(16) + h2.toString(16);
}

function render(tpl, vars) {
  return String(tpl || '')
    .replace(/\{\{\s*(\w+)\s*\}\}/g, function (m, k) {
      return (vars[k] === undefined || vars[k] === null) ? '' : String(vars[k]);
    })
    .replace(/\s+/g, ' ')
    .trim();
}

const out = [];
const deferred = [];
let plannedSends = 0;
const cap = Number(cfg.daily_send_cap) || 0;

for (const r of rows) {
  const seq = (Array.isArray(r.sequence) && r.sequence.length) ? r.sequence : cfg.sequence;
  const stepIndex = Number(r.step) || 0;

  // The ladder is finished and there was still silence. Terminal, and not a failure — most
  // people do not reply to a recruiter, and the row says `exhausted` rather than pretending
  // something went wrong.
  if (stepIndex >= seq.length) {
    deferred.push({
      enrollment_id: r.enrollment_id,
      action: 'exhaust',
      status: 'exhausted',
      next_attempt_at: null,
      reason: 'all ' + seq.length + ' touches sent, no reply'
    });
    continue;
  }

  const rung = seq[stepIndex];
  const tz = r.candidate_timezone || cfg.default_timezone;
  const p = localParts(null, tz);
  const weekend = p.weekday === 'Sat' || p.weekday === 'Sun';

  // DEMO_ANY_HOUR. Only ever true when DEMO_MODE is on, and DEMO_MODE forces preview, so
  // this cannot put a real message on a real phone at 3am — it just makes the walkthrough
  // filmable outside office hours.
  const skipQuiet = cfg.ignore_quiet_hours === true;

  if (!skipQuiet && (isQuiet(p.hour) || (!cfg.send_on_weekends && weekend))) {
    // Rescheduled, never dropped. The row stays in the queue with a new due time.
    deferred.push({
      enrollment_id: r.enrollment_id,
      action: 'defer',
      next_attempt_at: nextAllowed(tz),
      reason: isQuiet(p.hour)
        ? 'quiet hours - ' + p.hour + ':00 in ' + tz
        : 'weekend - ' + p.weekday + ' in ' + tz
    });
    continue;
  }

  if (cap && plannedSends >= cap) {
    deferred.push({
      enrollment_id: r.enrollment_id,
      action: 'defer',
      next_attempt_at: nextAllowed(tz),
      reason: 'daily send cap of ' + cap + ' reached'
    });
    continue;
  }

  const pay = Number(r.pay_rate);
  const clientName = r.client_slug
    ? (r.client_slug.charAt(0).toUpperCase() + r.client_slug.slice(1))
    : cfg.client_name;

  const vars = {
    first_name: r.first_name || 'there',
    last_name: r.last_name || '',
    job_title: r.job_title || 'a role',
    job_city: r.job_city || r.job_state || 'your area',
    recruiter_name: r.recruiter_name || 'the recruiting team',
    client_name: clientName,
    pay_phrase: (Number.isFinite(pay) && pay > 0) ? (' paying $' + pay.toFixed(2) + '/hr') : ''
  };

  const channel = rung.channel === 'voice' ? 'voice' : 'sms';
  const body = channel === 'sms' ? render(rung.template, vars) : '';

  const unicode = hasNonAscii(body);
  const perSegment = unicode ? 67 : 153;
  const segments = channel === 'sms' ? (Math.ceil(body.length / perSegment) || 1) : 0;

  const redirected = cfg.mode === 'test' && !!cfg.test_phone;

  out.push({
    enrollment_id: r.enrollment_id,
    client_id: r.client_id,
    campaign_id: r.campaign_id,
    candidate_id: r.candidate_id,
    job_order_id: r.job_order_id,

    to: redirected ? cfg.test_phone : r.phone_e164,
    real_to: r.phone_e164,
    _redirected: redirected,

    channel: channel,
    step: rung.step,
    step_index: stepIndex,
    body: redirected ? ('[TEST -> ' + r.phone_e164 + '] ' + body) : body,
    segments: segments,
    _long_sms: segments > 2,
    _has_unicode: unicode,

    // Everything the Retell agent is told. It is given facts and a job to do; it is never
    // given the decision, which is made from its structured answers in workflow 3.
    agent_note: rung.agent_note || '',
    retell_vars: {
      first_name: vars.first_name,
      job_title: vars.job_title,
      job_city: vars.job_city,
      pay_rate: vars.pay_phrase.replace('paying ', '').trim(),
      shift: r.shift || '',
      recruiter_name: vars.recruiter_name,
      company: clientName,
      note: rung.agent_note || ''
    },

    // Computed before the send. This is the whole duplicate-contact guarantee.
    idempotency_key: keyFor([r.enrollment_id, channel, String(rung.step)]),

    candidate_name: ((r.first_name || '') + ' ' + (r.last_name || '')).trim(),
    job_title: r.job_title,
    recruiter_email: r.recruiter_email,
    timezone: tz,
    local_hour: p.hour,
    match_score: r.match_score,
    attempts_made: Number(r.attempts_made) || 0,
    _tz_error: p._tz_error || ''
  });

  plannedSends++;
}

const deferredByReason = deferred.reduce(function (a, d) {
  const k = String(d.reason).replace(/\d+/g, 'N');
  a[k] = (a[k] || 0) + 1;
  return a;
}, {});

if (!out.length) {
  return [{
    json: {
      _has_work: false,
      due_rows: rows.length,
      deferred: deferred,
      deferred_by_reason: deferredByReason
    }
  }];
}

return out.map(function (o) {
  return {
    json: Object.assign(o, {
      _has_work: true,
      _due_rows: rows.length,
      _deferred: deferred,
      _deferred_by_reason: deferredByReason,
      _batch: out.length
    })
  };
});

// Nothing was due this pass. For a runner that fires every fifteen minutes this is the
// normal outcome for most of the day, so it reports the arithmetic rather than a bare
// "0 items" — an empty queue and a broken query look identical otherwise.
const j = $input.first().json;
const deferred = j.deferred || [];

return [{
  json: {
    _outcome: deferred.length ? 'everything due was deferred' : 'nothing due',
    rows_returned_by_the_queue: j.due_rows || 0,
    deferred: deferred.length,
    deferred_by_reason: j.deferred_by_reason || {},
    examples: deferred.slice(0, 8),
    // Deferred rows still need writing back, or they stay due and this node reports the
    // same thing every fifteen minutes forever.
    _has_deferrals: deferred.length > 0,
    _next_step: deferred.length
      ? 'These rows were rescheduled, not dropped. Quiet hours are evaluated in the '
        + 'candidate timezone, so a queue that defers everything at 07:00 Eastern is '
        + 'correct behaviour for a west-coast list.'
      : 'The queue returned no rows. Either no campaign is active, or every enrollment has '
        + 'a null next_attempt_at (replied, opted out, booked, or exhausted).'
  }
}];

// Preview. The queue was read, the ladder was walked, quiet hours were applied and every
// message was rendered — and nothing was sent.
//
// This is the node to have open on a screen-share. It shows the exact text each candidate
// would receive, at their local time, with the segment count next to it.
const cfg = $('config').first().json;
const items = $input.all().map((i) => i.json).filter((i) => i && i._has_work);
const first = items[0] || {};

const sms = items.filter((i) => i.channel === 'sms');
const voice = items.filter((i) => i.channel === 'voice');

return [{
  json: {
    _outcome: 'preview - nothing sent',
    _why: cfg.demo_mode
      ? 'DEMO_MODE is on. It forces preview whatever TEST_RUN says, because a fabricated '
        + 'Twilio response must never be able to reach a real phone.'
      : 'TEST_RUN is true with no TEST_PHONE set.',

    would_send: items.length,
    sms_count: sms.length,
    voice_count: voice.length,
    segments_total: sms.reduce((n, i) => n + (i.segments || 0), 0),
    deferred: (first._deferred || []).length,
    deferred_by_reason: first._deferred_by_reason || {},

    messages: sms.map((i) => ({
      to: i.real_to,
      name: i.candidate_name,
      step: i.step,
      local_time: i.local_hour + ':00 ' + i.timezone,
      segments: i.segments,
      unicode: i._has_unicode,
      body: i.body
    })),

    calls: voice.map((i) => ({
      to: i.real_to,
      name: i.candidate_name,
      step: i.step,
      local_time: i.local_hour + ':00 ' + i.timezone,
      agent: cfg.retell_agent || '(no agent id set)',
      brief: i.agent_note,
      variables_given_to_the_agent: i.retell_vars
    })),

    deferrals: first._deferred || [],

    warnings: [].concat(
      sms.filter((i) => i._long_sms).map((i) =>
        i.candidate_name + ': ' + i.segments + ' segments — you are paying ' + i.segments
          + 'x for this message'),
      sms.filter((i) => i._has_unicode).map((i) =>
        i.candidate_name + ': the template contains a non-ASCII character, which cuts the '
          + 'segment size from 153 to 67'),
      items.filter((i) => i._tz_error).map((i) =>
        i.candidate_name + ': unknown timezone "' + i._tz_error + '", quiet hours fell back to UTC')
    ),

    _next_step: 'Set DEMO_MODE = false, then put your own mobile in TEST_PHONE. Messages '
      + 'really send, to you, prefixed with the number they would have gone to. '
      + 'TEST_RUN = false is the separate, deliberate act that goes live.'
  }
}];

// Pairs each Twilio response back to the intent that produced it, and classifies the
// outcome into one of three things: sent, retry later, or never again.
//
// Pairing is by position within this branch. The Twilio node runs once per item and n8n
// preserves order inside a branch, so the i-th response belongs to the i-th SMS intent.
// It is done here rather than after the merge because the merge interleaves the SMS and
// voice branches and position stops meaning anything.
const cfg = $('config').first().json;
const permanent = (cfg.permanent_sms_errors || []).map(String);

const intents = $('decide the next touch').all()
  .map((i) => i.json)
  .filter((i) => i && i._has_work && i.channel === 'sms');

const responses = $input.all().map((i) => i.json);

// Twilio statuses that mean the message is on its way. `delivered` never appears here —
// it arrives minutes later on the status callback, which workflow 3 handles.
const ACCEPTED = ['queued', 'accepted', 'sending', 'sent', 'scheduled'];

return responses.map((res, idx) => {
  const intent = intents[idx] || {};

  // The HTTP node runs with onError: continueRegularOutput, so a 4xx arrives here as data
  // rather than ending the run. Twilio puts its own code in `code`; n8n wraps transport
  // failures in `error`.
  const err = res && (res.error || (res.status >= 400 ? res : null));
  const twilioCode = res && (res.code || (res.error && res.error.code));
  const sid = res && (res.sid || res.message_sid);
  const status = res && res.status;

  const accepted = !!sid && ACCEPTED.indexOf(String(status)) !== -1;
  const isPermanent = twilioCode && permanent.indexOf(String(twilioCode)) !== -1;

  let outcome;
  if (accepted) outcome = 'sent';
  else if (isPermanent) outcome = 'permanent';
  else if (err || !sid) outcome = 'transient';
  else outcome = 'sent';

  return {
    json: Object.assign({}, intent, {
      provider: 'twilio',
      provider_sid: sid || null,
      provider_status: status || null,
      outcome: outcome,
      error_code: twilioCode ? String(twilioCode) : null,
      error_message: err
        ? String((res.message || (res.error && res.error.message) || 'unknown Twilio error')).slice(0, 500)
        : null,
      // 21610 is Twilio's own opt-out list. Somebody replied STOP directly to the carrier
      // and it never reached our webhook, so this is the only place we learn about it —
      // and it has to be treated as an opt-out, not as a delivery failure.
      _carrier_opt_out: String(twilioCode) === '21610',
      _raw: res
    })
  };
});

// The run is live, but the provider for this channel has no keys. Used on both the Twilio
// and the Retell false branches.
//
// The touches are marked TRANSIENT, not permanent. A missing key is a configuration
// problem that someone will fix this afternoon, and marking a hundred candidates
// `undeliverable` because of it would quietly retire them from a campaign that is about to
// start working. They back off and come round again instead.
const cfg = $('config').first().json;
const items = $input.all().map((i) => i.json).filter((i) => i && i.enrollment_id);

if (!items.length) return [{ json: { _outcome: 'nothing on this branch', _empty: true } }];

const channel = items[0].channel;
const which = channel === 'voice' ? 'Retell' : 'Twilio';
const missing = channel === 'voice'
  ? ['RETELL_API_KEY', 'RETELL_AGENT_ID'].filter((k) =>
      (k === 'RETELL_API_KEY' ? !cfg.retell_key : !cfg.retell_agent))
  : ['TWILIO_ACCOUNT_SID', 'TWILIO_AUTH_TOKEN', 'TWILIO_FROM_NUMBER or TWILIO_MESSAGING_SID']
      .filter((k) => (k === 'TWILIO_ACCOUNT_SID' ? !cfg.twilio_sid
        : (k === 'TWILIO_AUTH_TOKEN' ? !cfg.twilio_token
          : !(cfg.twilio_from || cfg.twilio_messaging_sid))));

return items.map((i) => ({
  json: Object.assign({}, i, {
    provider: channel === 'voice' ? 'retell' : 'twilio',
    provider_sid: null,
    provider_status: null,
    outcome: 'transient',
    error_code: 'not_configured',
    error_message: which + ' is not configured — missing ' + missing.join(', '),
    _carrier_opt_out: false,
    _config_problem: true
  })
}));

// Pairs each Retell response back to the voice intent that produced it.
//
// A Retell create-call response only means the call was REGISTERED. Whether anyone picked
// up, what they said and whether they qualify all arrive later on the `call_analyzed`
// webhook, which workflow 3 handles. Treating a 201 here as "the candidate was screened"
// is the mistake that makes a voice pipeline report numbers nobody can reconcile.
const intents = $('decide the next touch').all()
  .map((i) => i.json)
  .filter((i) => i && i._has_work && i.channel === 'voice');

const responses = $input.all().map((i) => i.json);

return responses.map((res, idx) => {
  const intent = intents[idx] || {};

  const callId = res && (res.call_id || res.callId || (res.data && res.data.call_id));
  const err = res && (res.error || res.message || (res.status >= 400 ? res : null));
  const status = res && (res.call_status || res.status);

  // Retell rejects a call it cannot place at all — no agent, no from-number, a number it
  // will not dial. Those are configuration, not a bad moment, and retrying them every
  // fifteen minutes just burns the log.
  const text = String((res && (res.message || res.error_message)) || '').toLowerCase();
  const isPermanent = !callId && (
    text.includes('agent') || text.includes('not found') || text.includes('invalid')
    || text.includes('unsupported') || text.includes('forbidden'));

  return {
    json: Object.assign({}, intent, {
      provider: 'retell',
      provider_sid: callId || null,
      provider_status: status || (callId ? 'registered' : null),
      outcome: callId ? 'sent' : (isPermanent ? 'permanent' : 'transient'),
      error_code: callId ? null : String((res && res.code) || 'retell_error'),
      error_message: callId ? null : String(err || 'no call_id returned').slice(0, 500),
      _carrier_opt_out: false,
      // The call is registered and the result is pending. The enrollment does NOT advance
      // to "responded" here; only the webhook can do that.
      _awaiting_webhook: !!callId,
      _raw: res
    })
  };
});

// The run is live, but the provider for this channel has no keys. Used on both the Twilio
// and the Retell false branches.
//
// The touches are marked TRANSIENT, not permanent. A missing key is a configuration
// problem that someone will fix this afternoon, and marking a hundred candidates
// `undeliverable` because of it would quietly retire them from a campaign that is about to
// start working. They back off and come round again instead.
const cfg = $('config').first().json;
const items = $input.all().map((i) => i.json).filter((i) => i && i.enrollment_id);

if (!items.length) return [{ json: { _outcome: 'nothing on this branch', _empty: true } }];

const channel = items[0].channel;
const which = channel === 'voice' ? 'Retell' : 'Twilio';
const missing = channel === 'voice'
  ? ['RETELL_API_KEY', 'RETELL_AGENT_ID'].filter((k) =>
      (k === 'RETELL_API_KEY' ? !cfg.retell_key : !cfg.retell_agent))
  : ['TWILIO_ACCOUNT_SID', 'TWILIO_AUTH_TOKEN', 'TWILIO_FROM_NUMBER or TWILIO_MESSAGING_SID']
      .filter((k) => (k === 'TWILIO_ACCOUNT_SID' ? !cfg.twilio_sid
        : (k === 'TWILIO_AUTH_TOKEN' ? !cfg.twilio_token
          : !(cfg.twilio_from || cfg.twilio_messaging_sid))));

return items.map((i) => ({
  json: Object.assign({}, i, {
    provider: channel === 'voice' ? 'retell' : 'twilio',
    provider_sid: null,
    provider_status: null,
    outcome: 'transient',
    error_code: 'not_configured',
    error_message: which + ' is not configured — missing ' + missing.join(', '),
    _carrier_opt_out: false,
    _config_problem: true
  })
}));

// Turns send results into two things: an append-only attempt row for every touch, and the
// enrollment updates that move the state machine forward.
//
// The retry policy lives here, in one place, and it is three rules:
//
//   sent       -> advance a rung, schedule the next touch at the ladder's delay
//   transient  -> stay on this rung, come back with exponential backoff and jitter
//   permanent  -> stop. The number is wrong or the carrier will never deliver, and
//                 retrying it costs money and manufactures a fake "attempted 6 times"
//
// Jitter matters more than it looks. Without it, 300 enrollments that all failed on a
// Twilio blip retry in the same second, hit the same rate limit, and fail together again.
const cfg = $('config').first().json;
const results = $input.all().map((i) => i.json).filter((r) => r && r.enrollment_id);

// Deferrals were decided upstream and still have to be written, or the row stays due and
// the runner reconsiders it every fifteen minutes forever.
const decided = $('decide the next touch').all().map((i) => i.json);
const deferrals = (decided[0] && decided[0]._deferred) || [];

const seq = cfg.sequence || [];
const now = Date.now();

// 5min, 20min, 80min, 5h20, capped at 6h, plus up to 25% jitter.
function backoff(attempt) {
  const base = 5 * 60 * 1000 * Math.pow(4, Math.max(0, attempt));
  const capped = Math.min(base, 6 * 3600 * 1000);
  return new Date(now + capped * (1 + Math.random() * 0.25)).toISOString();
}

const attempts = [];
const enrollmentUpdates = [];
const optOuts = [];
const counts = { sent: 0, transient: 0, permanent: 0, carrier_opt_out: 0 };

for (const r of results) {
  const retry_count = Number(r.attempts_made) || 0;

  attempts.push({
    client_id: r.client_id || cfg.client_id || null,
    enrollment_id: r.enrollment_id,
    candidate_id: r.candidate_id,
    channel: r.channel,
    step: r.step,
    direction: 'outbound',
    provider: r.provider,
    provider_sid: r.provider_sid,
    status: r.outcome === 'sent'
      ? (r.channel === 'voice' ? 'queued' : 'sent')
      : (r.outcome === 'permanent' ? 'failed' : 'failed'),
    error_code: r.error_code,
    error_message: r.error_message,
    body: r.channel === 'sms' ? r.body : (r.agent_note || 'AI voice screening call'),
    retry_count: retry_count,
    sent_at: new Date(now).toISOString(),
    // Computed before the send, in `decide the next touch`. A unique-violation on this
    // insert is not an error — it means another execution already sent this exact touch.
    idempotency_key: r.idempotency_key
  });

  // Twilio's own suppression list answered. Nobody told our webhook, so this is the only
  // moment we find out, and it has to become a real opt-out rather than a failed send.
  if (r._carrier_opt_out) {
    counts.carrier_opt_out++;
    optOuts.push({
      client_id: r.client_id || cfg.client_id || null,
      phone_e164: r.real_to,
      channel: 'all',
      reason: 'carrier-level STOP (Twilio 21610)',
      source: 'twilio_21610'
    });
    enrollmentUpdates.push({
      id: r.enrollment_id, status: 'opted_out',
      next_attempt_at: null, lease_token: null, lease_expires_at: null,
      last_attempt_at: new Date(now).toISOString(),
      _why: 'carrier opt-out'
    });
    continue;
  }

  if (r.outcome === 'sent') {
    counts.sent++;
    const nextIndex = (Number(r.step_index) || 0) + 1;
    const nextRung = seq[nextIndex];
    enrollmentUpdates.push({
      id: r.enrollment_id,
      status: 'active',
      step: nextIndex,
      attempts_made: retry_count + 1,
      last_attempt_at: new Date(now).toISOString(),
      // No next rung means the ladder is done. A null due time takes the row out of the
      // queue without needing a separate "finished" flag anywhere.
      next_attempt_at: nextRung
        ? new Date(now + (Number(nextRung.delay_hours) || 0) * 3600 * 1000).toISOString()
        : null,
      lease_token: null,
      lease_expires_at: null,
      _why: nextRung ? ('sent step ' + r.step + ', next in ' + nextRung.delay_hours + 'h')
                     : ('sent step ' + r.step + ', ladder complete')
    });
    continue;
  }

  if (r.outcome === 'permanent') {
    counts.permanent++;
    enrollmentUpdates.push({
      id: r.enrollment_id,
      status: 'undeliverable',
      attempts_made: retry_count + 1,
      last_attempt_at: new Date(now).toISOString(),
      next_attempt_at: null,
      lease_token: null,
      lease_expires_at: null,
      _why: 'permanent failure ' + r.error_code + ' — will never deliver'
    });
    continue;
  }

  // Transient. Same rung, later. After enough tries it stops being transient.
  counts.transient++;
  const MAX_RETRIES = 4;
  const exhausted = retry_count >= MAX_RETRIES;
  enrollmentUpdates.push({
    id: r.enrollment_id,
    status: exhausted ? 'undeliverable' : 'active',
    attempts_made: retry_count + 1,
    last_attempt_at: new Date(now).toISOString(),
    next_attempt_at: exhausted ? null : backoff(retry_count),
    lease_token: null,
    lease_expires_at: null,
    _why: exhausted
      ? ('gave up after ' + (retry_count + 1) + ' transient failures (' + r.error_code + ')')
      : ('transient ' + (r.error_code || 'error') + ', retry ' + (retry_count + 1)
         + ' of ' + MAX_RETRIES)
  });
}

// Quiet hours, weekends and the daily cap. Rescheduled, and the lease released so another
// runner can pick them up the moment they come due.
for (const d of deferrals) {
  enrollmentUpdates.push({
    id: d.enrollment_id,
    status: d.status || undefined,
    next_attempt_at: d.next_attempt_at,
    lease_token: null,
    lease_expires_at: null,
    _why: d.reason
  });
}

return [{
  json: {
    _write: cfg.supabase_enabled && !cfg.dry_run_db,
    attempts: attempts,
    enrollment_updates: enrollmentUpdates.map((u) => {
      const clean = {};
      for (const k of Object.keys(u)) {
        if (k.charAt(0) !== '_' && u[k] !== undefined) clean[k] = u[k];
      }
      return clean;
    }),
    opt_outs: optOuts,
    explanations: enrollmentUpdates.map((u) => ({ id: u.id, action: u._why })),
    counts: counts,
    deferred: deferrals.length
  }
}];

// No database configured, so the attempts and the state changes this run decided were not
// written anywhere.
//
// In a demo that is exactly right and nothing is lost, because nothing was sent either.
// In a LIVE run it would be serious: messages would go out and the engine would forget it
// sent them, so the same person is texted again on the next pass. That cannot actually
// happen — `sending?` is gated on the same config and a run with no database never reaches
// a provider — but the warning says so plainly rather than leaving it to be inferred.
const cfg = $('config').first().json;
const j = $input.first().json || {};

const attempts = j.attempts || [];
const updates = j.enrollment_updates || [];

return [{
  json: {
    _outcome: 'not persisted — no database configured',
    _why: cfg.supabase_enabled
      ? 'DRY_RUN_DB is true: reads happen, writes do not.'
      : 'SUPABASE_URL and SUPABASE_SERVICE_KEY are blank in the config node.',

    would_have_written: {
      contact_attempts: attempts.length,
      enrollment_updates: updates.length,
      opt_outs: (j.opt_outs || []).length
    },

    // The whole decision, readable. This is the node to open on a screen-share to show
    // what the state machine did without a database behind it.
    attempts: attempts.map((a) => ({
      channel: a.channel, step: a.step, status: a.status,
      body: a.body, idempotency_key: a.idempotency_key
    })),
    state_changes: j.explanations || [],
    counts: j.counts || {},
    deferred: j.deferred || 0,

    _next_step: 'Fill in SUPABASE_URL and SUPABASE_SERVICE_KEY to persist. Until then the '
      + 'runner is a read-only simulation of itself: it decides correctly and forgets.'
  }
}];

// The runner posts a summary only when there is something worth reading. A workflow that
// fires every fifteen minutes and reports "0 sent" ninety-six times a day trains everyone
// to ignore it, and then nobody notices the morning it says "42 permanent failures".
const cfg = $('config').first().json;
const j = $input.first().json || {};

const preview = String(j._outcome || '').indexOf('preview') === 0;
const nothing = j._outcome === 'nothing due' || j._outcome === 'everything due was deferred';

const c = j.counts || {};
const sent = Number(c.sent) || 0;
const transient = Number(c.transient) || 0;
const permanent = Number(c.permanent) || 0;
const carrierOptOut = Number(c.carrier_opt_out) || 0;
const deferred = Number(j.deferred) || Number(j.deferred_count) || 0;

const lines = [];
const attention = [];

if (preview) {
  lines.push('*Outreach runner — preview*',
    (j.would_send || 0) + ' touches ready: ' + (j.sms_count || 0) + ' SMS, '
      + (j.voice_count || 0) + ' calls. Nothing was sent.');
  (j.warnings || []).forEach((w) => attention.push(w));
} else if (nothing) {
  lines.push('*Outreach runner*', j._outcome + ' — ' + (j.rows_returned_by_the_queue || 0)
    + ' rows in the queue, ' + (j.deferred || 0) + ' deferred.');
} else {
  const modeLabel = cfg.mode === 'live' ? '' : '  [' + String(cfg.mode).toUpperCase() + ']';
  lines.push('*Outreach runner*' + modeLabel,
    sent + ' sent · ' + deferred + ' deferred · ' + transient + ' retrying · '
      + permanent + ' undeliverable');

  if (carrierOptOut) {
    lines.push('', carrierOptOut + ' carrier-level opt-out'
      + (carrierOptOut === 1 ? '' : 's') + ' recorded (Twilio 21610).');
  }

  const notable = (j.explanations || [])
    .filter((e) => /gave up|permanent|carrier|undeliverable/.test(String(e.action)))
    .slice(0, 6);
  if (notable.length) {
    lines.push('', 'Stopped:');
    notable.forEach((e) => lines.push('• ' + e.id.slice(0, 8) + ' — ' + e.action));
  }

  if (permanent > 5) {
    attention.push(permanent + ' permanent failures in one pass. That is usually a phone '
      + 'field mapped to a landline column, not a bad batch of numbers.');
  }
  if (transient > sent && sent > 0) {
    attention.push('More transient failures than sends — check the Twilio account balance '
      + 'and the rate limit before the backoff spreads them over the next six hours.');
  }
}

if (attention.length) lines.push('', '*Needs attention*', ...attention.map((a) => '• ' + a));

// Only speak up when there is news, or when something is wrong.
const worthPosting = attention.length > 0 || sent > 0 || permanent > 0 || preview;

return [{
  json: {
    _outcome: j._outcome || 'runner complete',
    sent: sent,
    deferred: deferred,
    retrying: transient,
    undeliverable: permanent,
    carrier_opt_outs: carrierOptOut,
    needs_attention: attention,
    _post: worthPosting && cfg.slack_enabled,
    slack_text: lines.join('\n'),
    slack_payload: { text: lines.join('\n') }
  }
}];
